import random, time, httpx

def call_llm(payload, max_retry=4):
    for attempt in range(max_retry):
        try:
            r = httpx.post(URL, json=payload, timeout=(5, 60))
            if r.status_code == 429:
                wait = float(r.headers.get("retry-after", 0))
                wait = max(wait, min(30, 2 ** attempt) + random.uniform(0, 1))
                time.sleep(wait)          # 优先 Retry-After,退避+抖动兜底
                continue
            if r.status_code >= 500:
                time.sleep(min(10, 2 ** attempt) + random.random())
                continue
            if r.status_code >= 400:      # 400/401/403:重试无意义
                raise RuntimeError(f"非瞬时错误 {r.status_code}: {r.text[:200]}")
            return r.json()
        except httpx.TimeoutException:
            if attempt == max_retry - 1:
                raise
            time.sleep(min(10, 2 ** attempt))
    raise RuntimeError("重试次数耗尽")      # 上层接降级:备用模型/缓存
